import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. BUILD BACKDROP STAGE (engineered gradient)
  // ============================================================================
  const group = new THREE.Group();

  // Stage plane: ~7x6 units at z=-2.5, vertical gradient from surface to ink
  const stagePlane = new THREE.Mesh(
    new THREE.PlaneGeometry(7, 6),
    new THREE.MeshBasicMaterial({
      color: 0x0b0b10, // surface #0b0b10
    })
  );
  stagePlane.position.z = -2.5;
  group.add(stagePlane);

  // ============================================================================
  // 2. LOAD GRAIN TEXTURE (async, non-blocking)
  // ============================================================================
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // ============================================================================
  // 3. CREATE TEXT VIA fontAtlas
  // ============================================================================
  const textObject = ctx.fontAtlas.createText('Features', {
    fontSize: 96,
    color: '#e8ecf2', // paper color for contrast
    align: 'center',
  });
  group.add(textObject);

  // ============================================================================
  // 4. CREATE SPRITE PLANE WITH GRAIN TEXTURE
  // ============================================================================
  const atlasWidth = 512;
  const atlasHeight = 320;
  const regionX = 0;
  const regionY = 0;
  const regionW = 512;
  const regionH = 320;

  // Aspect ratio of atlas region
  const aspectRatio = regionW / regionH;

  // Create plane geometry (2x2 default, then scale to aspect)
  const planeGeo = new THREE.PlaneGeometry(aspectRatio * 1.5, 1.5);

  // Compute UV offsets for atlas region
  const uvOffsetX = regionX / atlasWidth;
  const uvOffsetY = regionY / atlasHeight;
  const uvScaleX = regionW / atlasWidth;
  const uvScaleY = regionH / atlasHeight;

  // Material using TSL nodes for texture mapping
  const uvNode = uv().mul(new THREE.Vector2(uvScaleX, uvScaleY)).add(new THREE.Vector2(uvOffsetX, uvOffsetY));

  const planeMaterial = new MeshBasicNodeMaterial({
    colorNode: new THREE.TextureNode(null).uv(uvNode),
  });

  const spritePlane = new THREE.Mesh(planeGeo, planeMaterial);
  spritePlane.position.set(0, 0.3, 0.1);

  // Apply texture when loaded
  texturePromise.then((texture) => {
    planeMaterial.colorNode = new THREE.TextureNode(texture).uv(uvNode);
    planeMaterial.needsUpdate = true;
  });

  group.add(spritePlane);

  // ============================================================================
  // 5. LIGHTING: Key + rim accent (no ambient; scene provides 0.6 ambient)
  // ============================================================================
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 3);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.7); // accent red rim
  rimLight.position.set(-2, 1, -3);
  group.add(rimLight);

  // ============================================================================
  // 6. RESOURCE CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    texturePromise.then((texture) => {
      texture.dispose();
    });
    planeGeo.dispose();
    planeMaterial.dispose();
    stagePlane.geometry.dispose();
    stagePlane.material.dispose();
  };

  group.userData.handlers = {};

  return group;
}
